package com.xjtu.iron.idempotent.starter;import com.xjtu.iron.idempotent.api.*;import com.xjtu.iron.idempotent.core.observation.IdempotencyMetrics;import io.micrometer.core.instrument.*;import java.time.Duration;/** 不把 idempotencyKey 放进 metric 标签，避免高基数。 */public final class MicrometerIdempotencyMetrics implements IdempotencyMetrics{private final MeterRegistry registry;public MicrometerIdempotencyMetrics(MeterRegistry registry){this.registry=registry;}public void recordAcquire(IdempotencyMode mode,String repository,String status){registry.counter("iron.idempotency.acquire","mode",mode.name(),"repository",repository,"status",status).increment();}public void recordExecution(IdempotencyMode mode,String repository,IdempotencyResultStatus status,Duration duration){Timer.builder("iron.idempotency.execution.duration").tag("mode",mode.name()).tag("repository",repository).tag("status",status.name()).register(registry).record(duration);}}
